import { getSignUpEmailInfo, type SignUpEmailInfoResponse } from '~/client';

export const useSignUpEmailInfo = defineQuery(() => {
  const userId = ref('');

  const {
    data: signUpEmailInfo,
    error,
    isLoading,
  } = useQuery({
    key: ['sign-up.email.info'],
    query: () => getSignUpEmailInfo({ composable: '$fetch', body: { user_id: userId } }),
    enabled: () => !!userId.value,
  });

  return {
    userId,
    signUpEmailInfo,
    error,
    isLoading,
  };
});
