<template>
  <section class="login h-full w-full flex flex-col">
    <div class="flex justify-end">
      <NuxtLink :to="{ name: 'login' }">
        <Button variant="secondary" size="sm">Log In</Button>
      </NuxtLink>
    </div>
    <div class="self-center flex flex-col gap-6 p-6 flex-auto w-full justify-center max-w-[552px] max-lg:px-0">
      <SignUpStepper v-model="stepIndex" />
      <template v-if="stepIndex === 2">
        <div class="flex flex-col gap-3">
          <h1 class="font-semibold text-2xl leading-6">Confirm Your Email</h1>
          <p class="text-sm text-description">
            We've sent a confirmation code to
            <strong>{{ signUpEmailInfo?.email || 'none' }}</strong>
            <br />
            Please check your inbox and a "spam" folder.
          </p>
        </div>
        <form ref="confirmationForm" class="flex flex-col gap-4" @submit.prevent="onConfirmEmail">
          <FormField
            v-slot="{ componentField, value }"
            name="code"
            :validate-on-blur="false"
            :validate-on-change="false"
            :validate-on-input="false"
            :validate-on-model-update="false"
          >
            <FormItem class="mx-auto">
              <Label>Code</Label>
              <FormControl>
                <PinInput
                  :model-value="value"
                  placeholder="○"
                  class="self-center py-2"
                  otp
                  type="text"
                  :name="componentField.name"
                  @update:model-value="
                    (arrStr) => {
                      setFieldValue('code', arrStr);
                    }
                  "
                >
                  <PinInputGroup>
                    <PinInputInput v-for="(id, index) in 6" :key="id" :index="index" class="h-12 w-12" />
                  </PinInputGroup>
                </PinInput>
              </FormControl>
              <FormMessage />
            </FormItem>
          </FormField>
          <Button variant="default" class="w-full h-10" :loading="isConfirmingEmail" type="submit">
            Confirm Email
          </Button>
        </form>
        <Separator class="mb-4 mt-8" label="Did not receive email?" />
        <div class="grid grid-cols-11">
          <Button
            variant="ghost"
            class="w-full h-10 col-span-5"
            :loading="isResendingEmail"
            :disabled="resendCounting"
            @click="onResendEmail"
          >
            Resend Email
            <VueCountdown
              v-show="resendCounting"
              ref="resendCountdown"
              v-slot="{ totalSeconds }"
              :time="60000"
              @end="onResendCountdownEnd"
              >{{ totalSeconds }}s
            </VueCountdown>
          </Button>
          <p class="col-span-1 text-sm text-description flex justify-center items-center">or</p>
          <EmailVerificationChangeEmail v-model:is-visible="isEmailChangeVisible" :user-id="userId">
            <Button :disabled="isResendingEmail" variant="ghost" class="w-full h-10 col-span-5"
              >Change Email Address
            </Button>
          </EmailVerificationChangeEmail>
        </div>
      </template>
      <template v-if="stepIndex === 3">
        <Alert variant="success">
          <CheckIcon />
          <AlertTitle>Account created</AlertTitle>
          <AlertDescription
            >Thank you for creating an account on Patriot Grassroots App.<br />
            You can log in now.
          </AlertDescription>
        </Alert>
        <NuxtLink :to="{ name: 'login' }" class="mx-auto">
          <Button variant="default" size="lg">Log In</Button>
        </NuxtLink>
      </template>
    </div>
  </section>
</template>

<script setup lang="ts">
import { useSignUpEmailInfo } from '~/queries/signUp/infoEmail';
import { useConfirmEmail } from '~/mutations/signUp/confirmEmail';
import { useResendEmail } from '~/mutations/signUp/resendEmail';
import { toTypedSchema } from '@vee-validate/zod';
import * as z from 'zod';
import { useForm } from 'vee-validate';
import VueCountdown from '@chenfengyuan/vue-countdown';
import { CheckIcon } from 'lucide-vue-next';

useSeoMeta({
  title: 'Email Verification',
  description: 'Verify your email and join our community of canvassers.',
});

definePageMeta({
  layout: 'login',
  auth: {
    unauthenticatedOnly: true,
    navigateAuthenticatedTo: '/projects',
  },
  // TODO: add middleware logics for checking if account is created and email is not verified currently, in other cases do not show this page and redirect to login or signup
});

const route = useRoute('sign-up-email-confirmation-user_id');

const confirmationForm = ref<HTMLFormElement | null>(null);
const stepIndex = computed(() => (route.query?.success === 'true' ? 3 : 2));
const resendCounting = ref(false);
const resendCountdown = ref<typeof VueCountdown | null>(null);

const { userId, isLoading: isEmailInfoLoading, signUpEmailInfo } = useSignUpEmailInfo();

const formSchema = toTypedSchema(
  z.object({
    code: z
      .string({ message: 'Code is required' })
      .array()
      .length(6, 'Code should contain 6 digits')
      .refine(
        (strArray) => {
          return strArray.every((char) => /^[0-9]$/.test(char));
        },
        {
          message: 'Code should contain only digits',
        }
      ),
  })
);

const { handleSubmit, setFieldValue } = useForm({
  validationSchema: formSchema,
  initialValues: {
    code: route.query?.code && route.query.code.length === 6 ? route.query.code.toString().split('') : [],
  },
});

const { confirmEmail, isConfirmingEmail } = useConfirmEmail();

const onConfirmEmail = handleSubmit(async (values) => {
  await confirmEmail({ user_id: userId.value, code: values.code.join('') }).catch(() => {});
});

onMounted(() => {
  userId.value = route.params.user_id?.toString() || '';

  if (route.query?.code?.length === 6 && confirmationForm.value) {
    confirmationForm.value?.requestSubmit();
  }
  if (resendCountdown.value) {
    resendCountdown.value.restart();
    resendCounting.value = true;
  }
});

function onResendCountdownEnd() {
  resendCounting.value = false;
}

const { resendEmail, isResendingEmail } = useResendEmail();

async function onResendEmail() {
  await resendEmail({ user_id: userId.value }).catch(() => {});
  if (resendCountdown.value) {
    resendCountdown.value.restart();
    resendCounting.value = true;
  }
}

const isEmailChangeVisible = ref<boolean>(false);
</script>

<style scoped lang="scss"></style>
