import { signUpChangeEmail, type SignUpEmailEditRequest, type SignUpEmailEditResponse } from '~/client';
import { showToastError, showToastSuccess } from '~/utils/show-toast';

export const useChangeEmail = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync: changeEmailMutation, asyncStatus } = useMutation({
    mutation: (form: SignUpEmailEditRequest): Promise<SignUpEmailEditResponse> =>
      signUpChangeEmail({
        composable: '$fetch',
        body: form,
      }),
    onSuccess: async (newData, form: SignUpEmailEditRequest) => {
      showToastSuccess('Email changed successfully', 'Code sent again');
      await queryCache.invalidateQueries({ key: ['sign-up.email.info'], exact: true });
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    changeEmail: changeEmailMutation,
    isChangingEmail: computed(() => asyncStatus.value === 'loading'),
  };
});
