import { signUpConfirmEmail, type SignUpEmailConfirmRequest, type SignUpEmailConfirmResponse } from '~/client';
import { showToastError } from '~/utils/show-toast';

export const useConfirmEmail = defineMutation(() => {
  const { mutateAsync: confirmEmailMutation, asyncStatus } = useMutation({
    mutation: (form: SignUpEmailConfirmRequest): Promise<SignUpEmailConfirmResponse> =>
      signUpConfirmEmail({ composable: '$fetch', body: form }),
    onSuccess: async (newData, form: SignUpEmailConfirmRequest) => {
      await navigateTo({
        name: 'sign-up-email-confirmation-user_id',
        params: { user_id: form.user_id },
        query: { success: 'true' },
      });
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    confirmEmail: confirmEmailMutation,
    isConfirmingEmail: computed(() => asyncStatus.value === 'loading'),
  };
});
