import { signUpResendConfirmationEmail, type SignUpEmailResendRequest, type SignUpEmailResendResponse } from '~/client';
import { showToastError, showToastSuccess } from '~/utils/show-toast';

export const useResendEmail = defineMutation(() => {
  const { mutateAsync: resendEmailMutation, asyncStatus } = useMutation({
    mutation: (form: SignUpEmailResendRequest): Promise<SignUpEmailResendResponse> =>
      signUpResendConfirmationEmail({
        composable: '$fetch',
        body: form,
      }),
    onSuccess: async (newData, form: SignUpEmailResendRequest) => {
      showToastSuccess('Code sent again');
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    resendEmail: resendEmailMutation,
    isResendingEmail: computed(() => asyncStatus.value === 'loading'),
  };
});
