<template>
  <Dialog v-model:open="isVisible">
    <DialogTrigger as-child>
      <slot />
    </DialogTrigger>
    <DialogContent class="max-w-sm gap-6">
      <DialogHeader class="gap-y-2 text-left">
        <DialogTitle class="text-xl">Change email address?</DialogTitle>
        <!--        <DialogDescription class="font-normal text-base text-accent-foreground w-10/12">-->
        <!--          Enter the new email address into the input below-->
        <!--        </DialogDescription>-->
        <form id="changeEmail" class="pt-2" @submit.prevent="onChangeEmail">
          <FormField
            v-slot="{ componentField }"
            :validate-on-model-update="false"
            :validate-on-blur="false"
            name="email"
          >
            <FormItem class="flex-auto">
              <FormControl>
                <Label for="email">New email</Label>
                <Input id="email" type="text" placeholder="name@example.com" v-bind="componentField" />
                <FormMessage />
              </FormControl>
            </FormItem>
          </FormField>
        </form>
      </DialogHeader>
      <DialogFooter>
        <div class="flex gap-2">
          <DialogClose as-child>
            <Button variant="outline" class="h-10 px-4" :disabled="isChangingEmail">Cancel</Button>
          </DialogClose>
          <Button variant="default" class="h-10 px-4" :loading="isChangingEmail" type="submit" form="changeEmail"
            >Change</Button
          >
        </div>
      </DialogFooter>
    </DialogContent>
  </Dialog>
</template>

<script setup lang="ts">
import { toTypedSchema } from '@vee-validate/zod';
import * as z from 'zod';
import { useForm } from 'vee-validate';
import { useChangeEmail } from '~/mutations/signUp/changeEmail';

const isVisible = defineModel<boolean>('isVisible', { required: true });
const props = defineProps({ userId: { type: String, required: true } });

const { changeEmail, isChangingEmail } = useChangeEmail();

const formSchema = toTypedSchema(
  z.object({
    email: z.string({ message: 'Email is required' }).trim().nonempty({ message: 'Email is required' }).email(),
  })
);

const { handleSubmit } = useForm({
  validationSchema: formSchema,
});

const onChangeEmail = handleSubmit(async (values) => {
  await changeEmail({ user_id: props.userId, email: values.email }).catch(() => {});
  isVisible.value = false;
});
</script>

<style scoped lang="scss"></style>
